/** Noms des emojis de l'application Discord. */
declare type EmojiName = ApplicationEmoji["name"];

/** IDs des emojis de l'application Discord. */
declare type EmojiId = ApplicationEmoji["id"];

/** ID correspondant à un nom d'emoji précis. */
declare type EmojiIdForName<Name extends EmojiName> = Extract<
  ApplicationEmoji,
  { name: Name }
>["id"];

/** Nom correspondant à un ID d'emoji précis. */
declare type EmojiNameForId<Id extends EmojiId> = Extract<ApplicationEmoji, { id: Id }>["name"];
